{
  "initiative": "Shorten the customer activation interval from a month to a matter of days",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Activation process mapping",
      "owner_role": "Customer Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Documented activation process map with cycle time measured at each step"
    },
    {
      "id": "WP-02",
      "title": "Handoff and data collection redesign",
      "owner_role": "Business Systems Lead",
      "duration_quarters": 1,
      "deliverable": "Redesigned handoff with automated data collection and documented controls"
    },
    {
      "id": "WP-03",
      "title": "Controlled release to all new accounts",
      "owner_role": "Customer Operations Director",
      "duration_quarters": 1,
      "deliverable": "New activation process released with training records complete"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Process map acceptance gate review",
      "approver_role": "Director of Customer Operations",
      "criteria": "Cycle time measurements verified against the source records with no deviations"
    },
    {
      "gate": "G3",
      "name": "Release gate review",
      "approver_role": "Vice President of Customer Operations",
      "criteria": "Pilot activations demonstrate the target interval with all controls in place"
    }
  ],
  "compliance_notes": [
    "Customer data collected during activation is handled under the existing data retention procedure; changes require privacy sign-off.",
    "Any non-conformance in the activation record is corrected before the account is marked complete."
  ],
  "risks": [
    {
      "risk": "Faster activation increases the rate of incomplete customer records",
      "mitigation": "Add a completeness control at the handoff and audit a sample each month",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "Three quarters from process map acceptance"
}

{
  "initiative": "Stop security review being the gate review that holds every release",
  "okrs": [
    {
      "objective": "Security assurance keeps up without a gate review on every change",
      "key_results": [
        "Low-risk changes clear without a formal gate review sign-off",
        "No open deviations in the monthly assurance sample"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-3",
      "focus": "Map the current gate review path end to end",
      "owner": "Security lead",
      "ships": "Documented gate review path with cycle time at each step"
    },
    {
      "sprint": 2,
      "weeks": "4-6",
      "focus": "Define risk tiers and their controls",
      "owner": "Security architect",
      "ships": "Tier definitions with a non-conformance escalation route"
    },
    {
      "sprint": 3,
      "weeks": "7-9",
      "focus": "Run the tiered model with sampling",
      "owner": "Security lead",
      "ships": "Tiered model live with sign-off retained for high-risk work only"
    }
  ],
  "blockers": [
    "Risk committee wants a documented sign-off before any tier goes live"
  ],
  "success_metric": "Median time from change request to security approval",
  "timeline_weeks": 9
}

{
  "initiative": "Get everyone onto one ticketing tool",
  "okrs": [
    {
      "objective": "One tool, one queue, one set of numbers",
      "key_results": [
        "All three teams working in a single tool",
        "Two legacy tools switched off"
      ]
    }
  ],
  "sprint_plan": [
    {
      "sprint": 1,
      "weeks": "1-3",
      "focus": "Map what each team actually needs",
      "owner": "IT operations lead",
      "ships": "Agreed requirement set across the three teams"
    },
    {
      "sprint": 2,
      "weeks": "4-7",
      "focus": "Configure and migrate the biggest team",
      "owner": "Platform engineer",
      "ships": "Largest team live on the target tool"
    },
    {
      "sprint": 3,
      "weeks": "8-10",
      "focus": "Migrate the other two and switch off",
      "owner": "Platform engineer",
      "ships": "Remaining teams migrated, legacy tools off"
    }
  ],
  "blockers": [
    "One team has automations nobody has documented"
  ],
  "success_metric": "Number of active ticketing systems in use",
  "timeline_weeks": "10"
}
